```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    ifstream f1("uczniowie.txt"), f2("testy.txt");
    map<int, string> imiona;
    map<int, string> klasy;
    int id; string imie, klasa;
    while (f1 >> id >> imie >> klasa) {
        imiona[id] = imie;
        klasy[id] = klasa;
    }

    map<int, int> sumUczen;
    map<int, int> cntUczen;
    map<string, int> sumKlasa;
    map<string, int> cntKlasa;
    int uid, wynik;
    string przedmiot;
    while (f2 >> uid >> przedmiot >> wynik) {
        sumUczen[uid] += wynik;
        cntUczen[uid]++;
        sumKlasa[klasy[uid]] += wynik;
        cntKlasa[klasy[uid]]++;
    }

    cout << fixed << setprecision(2);
    cout << "a) Sredni wynik ucznia:" << endl;
    double maxAvg = 0;
    string maxImie;
    for (auto &u : imiona) {
        double avg = (double)sumUczen[u.first] / cntUczen[u.first];
        cout << "   " << u.second << ": " << avg << endl;
        if (avg > maxAvg) {
            maxAvg = avg;
            maxImie = u.second;
        }
    }

    cout << endl << "b) Sredni wynik klasy:" << endl;
    for (auto &k : sumKlasa) {
        cout << "   " << k.first << ": " << (double)k.second / cntKlasa[k.first] << endl;
    }

    cout << endl << "c) Najlepszy uczen: " << maxImie << " (" << maxAvg << ")" << endl;
    return 0;
}
```

